// Routes a question to one of several deterministic handlers so common investigation
// questions get a useful, cited response instead of a dead end. Nothing here is
// generated by a language model: every handler quotes records or counts metadata.
import {THEMES, theme, baseline, tokens, normalize} from './engine.mjs';

const CHANNELS = {
  support: /\b(support|tickets?|helpdesk)\b/,
  interview: /\binterview(s|ees)?\b/,
  survey: /\bsurveys?\b/,
};
export const CHANNEL_LABELS = {all: 'all channels', support: 'support tickets', interview: 'interviews', survey: 'surveys'};

// Words that name a theme in a question ("tell me about billing").
const THEME_WORDS = {
  Onboarding: /\b(onboarding|signups?|sign-?ups?|getting started|new accounts?|accounts?|invites?|invitations?|login)\b/,
  Billing: /\b(billing|bills?|invoices?|payments?|charges?|pricing|subscriptions?|receipts?)\b/,
  Search: /\bsearch(es|ing)?\b/,
  Exports: /\b(exports?|exporting|csv|pdf|downloads?)\b/,
  Permissions: /\b(permissions?|access|roles?|admins?|private projects?)\b/,
  Notifications: /\b(notifications?|alerts?|digests?|emails?)\b/,
};

// Kinds of question that can be answered from record metadata. Order matters.
const FACETS = [
  ['compare', /\b(compare|comparison|versus|vs|difference between|by channel|across channels|each channel)\b/],
  ['count', /\b(how many|number of|count of|count)\b/],
  ['requests', /\b(feature requests?|requests?|requested|want us to (build|add|make)|wish(es)?|would like|asking for|ask for|suggestions?|ideas?)\b/],
  ['praise', /\b(like|likes|love|loves|working well|works well|going well|positive|praise|happy|helpful|enjoy|good|great|good things?)\b/],
  ['recent', /\b(recent|recently|latest|newest|this week|last week|new feedback)\b/],
  ['severity', /\b(high[- ](priority|severity)|urgent|critical|severe|severity|blockers?|blocking|most important|worst|high[- ]priority|prioriti[sz]e|priorities|fix first|focus on)\b/],
  ['overview', /\b(top|main|summari[sz]e|summary|overview|common|key (issues|themes)|biggest|what are (users|people|customers) saying|themes|hate|dislike|frustrat\w*|pain points?|complain\w*|broken|wrong|unhappy)\b/],
];
const HELP = /^(hi|hello|hey|help|thanks|thank you)\b|what (can|should) (i|you) ask|what can you do|how (do i|does this) work|what (data|questions)/;
const SENSITIVE = /\b(api[- ]?keys?|passwords?|passcodes?|credentials?|secrets?|routing numbers?|account numbers?|bank|credit cards?|ssn|social security)\b/;
// Generic words that carry no topic once facets and themes are removed.
const GENERIC = new Set(['issu', 'thing', 'customer', 'top', 'list', 'everyth', 'anyth', 'overall', 'product', 'right', 'now', 'today', 'just', 'some', 'many', 'most', 'other', 'kind', 'type', 'thi', 'week', 'build', 'next', 'should', 'first', 'anyth', 'anybody', 'peopl', 'record', 'entri', 'there', 'total', 'altogether']);

const LISTING_LIMIT = 6;
const SEVERITY_RANK = {high: 0, medium: 1, low: 2};
const PRAISE_RULE = /\b(helped|helpful|easier|easy|quickly|saves)\b/i;
const REQUEST_RULE = /\b(please|i want|we need|let me|would like)\b/i;

const isFixture = r => r.severity === 'unrated';
const byPriority = (a, b) => (SEVERITY_RANK[a.severity] ?? 3) - (SEVERITY_RANK[b.severity] ?? 3) || b.date.localeCompare(a.date) || a.id.localeCompare(b.id);
const quote = r => ({text: r.text, evidence: [{source_id: r.id, quote: r.text}]});
const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;

export const SUGGESTIONS = {
  general: ['What are the top issues?', 'What feature requests do users have?', 'What do users like?', 'Which issues are most urgent?'],
  Onboarding: 'Tell me about onboarding',
  Billing: 'Tell me about billing',
  Search: 'Tell me about search',
  Exports: 'Tell me about exports',
  Permissions: 'Tell me about permissions',
  Notifications: 'Tell me about notifications',
};

function listing({intent, title, records, rule, scope, extra = {}}) {
  const shown = records.slice(0, LISTING_LIMIT);
  return {
    intent, status: 'answered', mode: 'extractive', title, rule, scope,
    claims: shown.map(quote), sources: shown,
    more: Math.max(0, records.length - shown.length),
    ...extra,
  };
}

function themeSummary(records) {
  return THEMES.map(name => {
    const inTheme = records.filter(r => theme(r) === name);
    return {theme: name, count: inTheme.length, high: inTheme.filter(r => r.severity === 'high').length};
  }).filter(t => t.count).sort((a, b) => b.high - a.high || b.count - a.count || a.theme.localeCompare(b.theme));
}

function detect(question) {
  const text = normalize(question);
  const themes = Object.entries(THEME_WORDS).filter(([, re]) => re.test(text)).map(([name]) => name);
  const facet = FACETS.find(([, re]) => re.test(text))?.[0] || null;
  const channel = Object.entries(CHANNELS).find(([, re]) => re.test(text))?.[0] || null;
  // What remains once facet, theme and channel words are removed decides whether the
  // question is about something specific ("Why do large exports time out?").
  let rest = text;
  for (const [, re] of FACETS) rest = rest.replace(new RegExp(re.source, 'g'), ' ');
  for (const re of Object.values(THEME_WORDS)) rest = rest.replace(new RegExp(re.source, 'g'), ' ');
  for (const re of Object.values(CHANNELS)) rest = rest.replace(new RegExp(re.source, 'g'), ' ');
  const residual = tokens(rest).filter(t => !GENERIC.has(t));
  return {themes, facet, channel, residual};
}

function facetAnswer(facet, pool, themes, scope) {
  const themeNote = themes.length ? ` in ${themes.join(' and ')}` : '';
  const inThemes = themes.length ? pool.filter(r => themes.includes(theme(r))) : pool;
  switch (facet) {
    case 'overview': {
      const summary = themeSummary(inThemes);
      const top = summary.map(t => inThemes.filter(r => theme(r) === t.theme).sort(byPriority)[0]);
      return listing({intent: 'overview', scope, records: top,
        title: `Themes in ${CHANNEL_LABELS[scope]}${themeNote}, ranked by high-severity records`,
        rule: 'Counts use keyword theme rules and authored severity labels. One highest-priority record is quoted per theme.',
        extra: {summary}});
    }
    case 'severity': {
      const high = inThemes.filter(r => r.severity === 'high').sort(byPriority);
      if (!high.length) return null;
      return listing({intent: 'severity', scope, records: high,
        title: `${plural(high.length, 'high-severity record')}${themeNote} in ${CHANNEL_LABELS[scope]}`,
        rule: 'Severity is an authored label on each synthetic record, not a model prediction.'});
    }
    case 'requests': {
      const asks = inThemes.filter(r => REQUEST_RULE.test(r.text)).sort(byPriority);
      if (!asks.length) return null;
      return listing({intent: 'requests', scope, records: asks,
        title: `${plural(asks.length, 'feature request')}${themeNote} in ${CHANNEL_LABELS[scope]}`,
        rule: 'Requests are records phrased as asks (“please”, “I want”, “we need”, “let me”). Keyword rule, not intent classification.'});
    }
    case 'praise': {
      const good = inThemes.filter(r => PRAISE_RULE.test(r.text)).sort(byPriority);
      if (!good.length) return null;
      return listing({intent: 'praise', scope, records: good,
        title: `${plural(good.length, 'positive record')}${themeNote} in ${CHANNEL_LABELS[scope]}`,
        rule: 'Positive records contain words such as “helped”, “easier” or “saves”. Keyword rule, not sentiment analysis.'});
    }
    case 'recent': {
      const latest = [...inThemes].sort((a, b) => b.date.localeCompare(a.date) || a.id.localeCompare(b.id)).slice(0, 5);
      return listing({intent: 'recent', scope, records: latest,
        title: `Latest ${latest.length} records${themeNote} in ${CHANNEL_LABELS[scope]}`,
        rule: 'Sorted by record date, newest first.'});
    }
    case 'compare': {
      const channels = Object.keys(CHANNELS).map(c => {
        const inChannel = inThemes.filter(r => r.channel === c);
        return {channel: c, count: inChannel.length, high: inChannel.filter(r => r.severity === 'high').length, top: inChannel.sort(byPriority)[0]};
      }).filter(c => c.count);
      return listing({intent: 'compare', scope, records: channels.map(c => c.top),
        title: `Feedback${themeNote} by channel: ${channels.map(c => `${CHANNEL_LABELS[c.channel]} ${c.count} (${c.high} high)`).join(' · ')}`,
        rule: 'Counts per channel with authored severity. One highest-priority record is quoted per channel.',
        extra: {channels: channels.map(({top, ...c}) => c)}});
    }
    case 'count': {
      if (!themes.length) {
        const summary = themeSummary(pool);
        const top = summary.map(t => pool.filter(r => theme(r) === t.theme).sort(byPriority)[0]);
        return listing({intent: 'count', scope, records: top,
          title: `${plural(pool.length, 'record')} in ${CHANNEL_LABELS[scope]} across ${plural(summary.length, 'theme')}`,
          rule: 'Counts records in this synthetic library by keyword theme, excluding test fixtures. Not a measure of how many customers are affected. One record is quoted per theme.',
          extra: {summary}});
      }
      const summary = themeSummary(inThemes);
      const total = inThemes.length;
      return listing({intent: 'count', scope, records: [...inThemes].sort(byPriority),
        title: `${plural(total, 'record')}${themeNote} in ${CHANNEL_LABELS[scope]} (${summary.reduce((n, t) => n + t.high, 0)} high severity)`,
        rule: 'Counts records in this synthetic library by keyword theme. Not a measure of how many customers are affected.',
        extra: {summary}});
    }
    default:
      return null;
  }
}

// Maps internal stems (e.g. "acm") back to the words the person typed ("acme").
function typedWords(question, stems) {
  const words = new Map();
  for (const word of String(question).match(/[A-Za-z0-9']+/g) || []) {
    const t = tokens(word)[0];
    if (t && !words.has(t)) words.set(t, word.toLowerCase());
  }
  return stems.map(t => words.get(t) || t);
}

function outOfScope({question, scoped, pool, scope, retrieval, allRecords}) {
  const relatedThemes = [...new Set((retrieval.related || []).map(r => theme(pool.find(p => p.id === r.id) || {text: ''})))]
    .filter(t => t !== 'Other');
  const suggestions = [...relatedThemes.map(t => SUGGESTIONS[t]), ...SUGGESTIONS.general].slice(0, 4);
  const coverage = themeSummary(scoped.filter(r => !isFixture(r))).map(t => `${t.theme.toLowerCase()} (${t.count})`).join(', ');
  let broaden = 0;
  if (scope !== 'all') broaden = baseline(question, allRecords.filter(r => !isFixture(r))).sources.length;
  return {
    intent: 'out_of_scope', status: 'insufficient_evidence', mode: 'extractive', scope,
    title: `No feedback in ${CHANNEL_LABELS[scope]} answers this.`,
    message: `This library holds product feedback about ${coverage || 'nothing in this scope'}. It does not contain business metrics, finances, people data or outside facts, so Feedback Lens will not guess.`,
    claims: [], sources: [], retrieval, suggestions, broaden,
  };
}

// question: the user's text. records: the full corpus. channel: the selected scope.
export function answerQuestion(question, records, {channel = 'all'} = {}) {
  const text = normalize(question).trim();
  const {themes, facet, channel: mentioned, residual} = detect(text);
  let scope = channel;
  let scopeNote = '';
  if (channel === 'all' && mentioned && facet !== 'compare') {
    scope = mentioned;
    scopeNote = `Your question mentions ${CHANNEL_LABELS[mentioned]}, so only those records were used.`;
  }
  const scoped = scope === 'all' ? records : records.filter(r => r.channel === scope);
  const pool = scoped.filter(r => !isFixture(r));
  const finish = answer => ({scope_note: scopeNote, ...answer, scope});

  if (SENSITIVE.test(text)) {
    return finish({intent: 'sensitive', status: 'declined', mode: 'extractive', claims: [], sources: [],
      title: 'Feedback Lens does not hold credentials or financial account data.',
      message: 'The library contains only synthetic product feedback. One record (FB-031) is a deliberate prompt-injection test that mentions an API key; it is test data, not a secret.',
      suggestions: SUGGESTIONS.general});
  }
  if (HELP.test(text) || (!tokens(text).length && !facet && !themes.length)) {
    return finish({intent: 'help', status: 'help', mode: 'extractive', claims: [], sources: [],
      title: 'Ask about product feedback in this library.',
      message: 'You can ask about a specific problem (“Why do large exports time out?”), a theme (“Tell me about billing”), urgency, feature requests, what users like, recent feedback or counts. Every answer quotes the records it used.',
      suggestions: [...SUGGESTIONS.general, SUGGESTIONS.Exports]});
  }

  // 1. A specific question, or one whose terms all appear together in records: search first.
  const search = baseline(question, scoped);
  const strong = search.status === 'answered' && search.sources.every(r => r.matched_terms.length >= 2);
  if ((residual.length || strong) && search.status === 'answered') return finish({...search, intent: 'search'});

  // 2. A facet question ("urgent", "requests", "top issues"), optionally within themes.
  // Skipped when the question also names something no record mentions ("mobile app"),
  // so a generic listing is never presented as the answer to a more specific question.
  if (facet && !residual.length) {
    const answer = facetAnswer(facet, pool, themes, scope);
    if (answer) return finish(answer);
  }
  const inThemes = pool.filter(r => themes.includes(theme(r))).sort(byPriority);
  // 3. A theme question ("Tell me about billing").
  if (inThemes.length && !residual.length) {
    return finish(listing({intent: 'theme', scope, records: inThemes,
      title: `${plural(inThemes.length, 'record')} about ${themes.join(' and ')} in ${CHANNEL_LABELS[scope]}`,
      rule: 'Theme membership uses keyword rules. Records are ordered by authored severity, then date.'}));
  }
  // 4. A search with weaker evidence still beats nothing.
  if (search.status === 'answered') return finish({...search, intent: 'search'});
  // 5. Specific but unanswerable within a known theme: say so, then show the theme's records.
  if (inThemes.length) {
    const shown = inThemes.slice(0, LISTING_LIMIT);
    return finish({...outOfScope({question, scoped, pool, scope, retrieval: search.retrieval, allRecords: records}),
      intent: 'related',
      title: `No record in ${CHANNEL_LABELS[scope]} answers this directly.`,
      message: `Nothing matches the specific part of your question (${typedWords(question, search.retrieval.missing_terms).join(', ') || 'its wording'}). Here is the related ${themes.join(' and ')} feedback so you can check for yourself. These records are context, not an answer.`,
      related_records: shown});
  }
  return finish(outOfScope({question, scoped, pool, scope, retrieval: search.retrieval, allRecords: records}));
}
